-- Four coasters from the 2026-11-19 adds took their stats from the wrong
-- Coasterpedia page: when one name covered rides at several parks (Oriental
-- Heritage, Fantawild Land) or two rides at one park (Butterfly at Schloss
-- Thurn, 1993 and 2022), addOpenCoaster read the first page in the list, not
-- the one linked to the coaster. Each is rebuilt from the page it IS linked to
-- (open_links): manufacturer, stats, dates, and where each value came from.
-- Found 2026-11-19 while splitting Oriental Heritage (198). Re-running sets
-- the same values again.

-- 2322: Jungle Trailblazer (Oriental Heritage Xiamen) (was read from Jungle Trailblazer (Oriental Heritage Anhui))
UPDATE coasters SET manu = COALESCE((SELECT value FROM open_record_facts WHERE source = 'coasterpedia' AND ref = 'Jungle Trailblazer (Oriental Heritage Xiamen)' AND field = 'manu'), manu), h = CAST((SELECT value FROM open_record_facts WHERE source = 'coasterpedia' AND ref = 'Jungle Trailblazer (Oriental Heritage Xiamen)' AND field = 'h') AS REAL), s = CAST((SELECT value FROM open_record_facts WHERE source = 'coasterpedia' AND ref = 'Jungle Trailblazer (Oriental Heritage Xiamen)' AND field = 's') AS REAL), l = CAST((SELECT value FROM open_record_facts WHERE source = 'coasterpedia' AND ref = 'Jungle Trailblazer (Oriental Heritage Xiamen)' AND field = 'l') AS REAL), inv = CAST((SELECT value FROM open_record_facts WHERE source = 'coasterpedia' AND ref = 'Jungle Trailblazer (Oriental Heritage Xiamen)' AND field = 'inv') AS INTEGER), dur = CAST((SELECT value FROM open_record_facts WHERE source = 'coasterpedia' AND ref = 'Jungle Trailblazer (Oriental Heritage Xiamen)' AND field = 'dur') AS INTEGER), opened = (SELECT value FROM open_record_facts WHERE source = 'coasterpedia' AND ref = 'Jungle Trailblazer (Oriental Heritage Xiamen)' AND field = 'opened'), openedPrec = CASE length((SELECT value FROM open_record_facts WHERE source = 'coasterpedia' AND ref = 'Jungle Trailblazer (Oriental Heritage Xiamen)' AND field = 'opened')) WHEN 4 THEN 'year' WHEN 7 THEN 'month' WHEN 10 THEN 'day' END, yr = CAST(substr((SELECT value FROM open_record_facts WHERE source = 'coasterpedia' AND ref = 'Jungle Trailblazer (Oriental Heritage Xiamen)' AND field = 'opened'), 1, 4) AS INTEGER), closed = (SELECT value FROM open_record_facts WHERE source = 'coasterpedia' AND ref = 'Jungle Trailblazer (Oriental Heritage Xiamen)' AND field = 'closed'), closedPrec = CASE length((SELECT value FROM open_record_facts WHERE source = 'coasterpedia' AND ref = 'Jungle Trailblazer (Oriental Heritage Xiamen)' AND field = 'closed')) WHEN 4 THEN 'year' WHEN 7 THEN 'month' WHEN 10 THEN 'day' END WHERE id = 2322;
DELETE FROM coaster_sources WHERE coaster_id = 2322 AND source = 'coasterpedia' AND ref = 'Jungle Trailblazer (Oriental Heritage Anhui)';
INSERT OR REPLACE INTO coaster_sources (coaster_id, field, source, ref) SELECT 2322, field, 'coasterpedia', ref FROM open_record_facts WHERE source = 'coasterpedia' AND ref = 'Jungle Trailblazer (Oriental Heritage Xiamen)' AND field IN ('manu','h','s','l','inv','dur','opened','closed') AND value IS NOT NULL AND value <> '';
DELETE FROM open_facts WHERE coaster_id = 2322 AND source = 'coasterpedia' AND ref = 'Jungle Trailblazer (Oriental Heritage Anhui)';
INSERT OR REPLACE INTO open_facts (coaster_id, field, value, prec, source, ref, cites_rcdb) SELECT 2322, field, value, prec, 'coasterpedia', ref, cites_rcdb FROM open_record_facts WHERE source = 'coasterpedia' AND ref = 'Jungle Trailblazer (Oriental Heritage Xiamen)';
